beforeSaveCustomScript:
name = string\trim(string\concatenate(nome, ' ', cognome));

if (cf != null) {
    cf = string\upperCase(string\trim(cf));
}

if (provincia != null) {
    provincia = string\upperCase(string\trim(provincia));
}

$today = datetime\today();
$startOk = ifThenElse(dataIngresso == null, true, dataIngresso <= $today);
$endOk = ifThenElse(dataDimissione == null, true, dataDimissione >= $today);
stato = ifThenElse($startOk && $endOk, 'Attivo', 'Inattivo');
